function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof AKBAR_INFO&&(n.innerHTML=AKBAR_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderCoins(){const n=document.getElementById("coins-grid");n&&"undefined"!=typeof COIN_TYPES&&(n.innerHTML=COIN_TYPES.map(n=>`\n        <div class="coin-card">\n            <h3>🪙 ${n.name}</h3>\n            <p><strong>Mint:</strong> ${n.mint}</p>\n            <p><strong>Metal & Weight:</strong> ${n.metal}</p>\n            <p><strong>Shape:</strong> ${n.shape}</p>\n            <p><strong>Obverse:</strong> <em>"${n.obverseText}"</em></p>\n            <p><strong>Reverse:</strong> <em>"${n.reverseText}"</em></p>\n            <p class="coin-sig"><strong>Significance:</strong> ${n.significance}</p>\n        </div>\n    `).join(""))}function initConverter(){const n=document.getElementById("btn-convert"),e=document.getElementById("regnal-year-input"),t=document.getElementById("convert-result");n&&e&&t&&n.addEventListener("click",()=>{const n=parseInt(e.value,10);if(isNaN(n)||n<1||n>50)return void(t.textContent="Please enter a valid Regnal Year between 1 and 50.");const o=1555+n;t.innerHTML=`✨ <strong>Ilahi Regnal Year ${n}</strong> corresponds to approximately <strong>${o} CE</strong> in the Gregorian calendar.`})}function renderMonths(){const n=document.getElementById("months-grid");n&&"undefined"!=typeof ILAHI_MONTHS&&(n.innerHTML=ILAHI_MONTHS.map(n=>`\n        <div class="month-card">\n            <h3>☀️ ${n.name}</h3>\n            <p><strong>Gregorian:</strong> ${n.gregorianEquivalent}</p>\n            <p><strong>Season:</strong> ${n.season}</p>\n        </div>\n    `).join(""))}function renderHotspots(){const n=document.getElementById("hotspots-grid");n&&"undefined"!=typeof INSCRIPTION_HOTSPOTS&&(n.innerHTML=INSCRIPTION_HOTSPOTS.map(n=>`\n        <div class="hotspot-card">\n            <h3>✨ ${n.phrase}</h3>\n            <p><strong>Literal Translation:</strong> ${n.literalMeaning}</p>\n            <p><strong>Historical Context:</strong> ${n.context}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderCoins(),initConverter(),renderMonths(),renderHotspots(),renderTimeline(),renderReferences(),initThemeToggle()});